"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Select from "react-select";
import toast from "react-hot-toast";

export default function Page() {
  const router = useRouter();

  /* ================= STATE ================= */
  const [rawData, setRawData] = useState<any[]>([]);
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const [divisionOptions, setDivisionOptions] = useState<any[]>([]);
  const [selectedDivision, setSelectedDivision] = useState<any>(null);

  // pagination
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;

  /* ================= FETCH DIVISION ================= */
  useEffect(() => {
    const fetchDivision = async () => {
      try {
        const res = await fetch("http://localhost:3001/api/division", {
          headers: { "lp3i-api-key": "aEof9XqcH34k3g6IbJcQLxGY" },
        });
        const json = await res.json();

        setDivisionOptions(
          json.data.map((d: any) => ({
            value: String(d.id),
            label: d.division,
          }))
        );
      } catch (err) {
        console.error(err);
      }
    };

    fetchDivision();
  }, []);

  /* ================= FETCH EMPLOYEE ================= */
  const fetchEmployee = async () => {
    try {
      setLoading(true);
      const res = await fetch("http://localhost:3001/api/employee", {
        headers: { "lp3i-api-key": "aEof9XqcH34k3g6IbJcQLxGY" },
      });
      const json = await res.json();

      setRawData(json.data);
      setData(json.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEmployee();
  }, []);

  /* ================= FILTER DIVISI ================= */
  useEffect(() => {
    if (!selectedDivision) {
      setData(rawData);
    } else {
      setData(
        rawData.filter(
          (item) =>
            String(item.division_id) === String(selectedDivision.value)
        )
      );
    }
    setCurrentPage(1);
  }, [selectedDivision, rawData]);

  /* ================= PAGINATION ================= */
  const totalPages = Math.ceil(data.length / itemsPerPage);
  const paginatedData = data.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  /* ================= RENDER ================= */
  return (
    <div className="p-6">
      {/* HEADER */}
      <div className="flex justify-between items-center mb-4">
        <h1 className="text-xl font-semibold">Data Karyawan</h1>

        {/* TOMBOL TIDAK DIHAPUS */}
        <div className="flex gap-2">
          <button className="px-4 py-2 bg-emerald-500 text-white rounded-xl text-sm">
            Tambah
          </button>
          <button className="px-4 py-2 bg-sky-500 text-white rounded-xl text-sm">
            Export
          </button>
        </div>
      </div>

      {/* FILTER */}
      <div className="flex gap-2 mb-4">
        <div className="w-72">
          <Select
            options={divisionOptions}
            value={selectedDivision}
            onChange={setSelectedDivision}
            placeholder="Pilih Divisi"
            className="text-sm"
            isClearable
          />
        </div>
        <button className="px-4 py-2 bg-sky-100 text-sky-500 rounded-xl hover:bg-sky-200 text-sm flex items-center">
          <i className="fi fi-bs-search mr-2" />
          Filter
        </button>
      </div>

      {/* TABLE */}
      <div className="overflow-x-auto">
        <table className="w-full border text-sm">
          <thead className="bg-gray-100">
            <tr>
              <th className="p-2 border">No</th>
              <th className="p-2 border">NIK</th>
              <th className="p-2 border">Nama</th>
              <th className="p-2 border">Divisi</th>
              <th className="p-2 border">Posisi</th>
              <th className="p-2 border">Aksi</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={6} className="text-center p-4">
                  Loading...
                </td>
              </tr>
            ) : paginatedData.length === 0 ? (
              <tr>
                <td colSpan={6} className="text-center p-4">
                  Data tidak ditemukan
                </td>
              </tr>
            ) : (
              paginatedData.map((item, index) => (
                <tr key={item.id}>
                  <td className="border p-2 text-center">
                    {(currentPage - 1) * itemsPerPage + index + 1}
                  </td>
                  <td className="border p-2">{item.nik}</td>
                  <td className="border p-2">{item.users?.[0]?.name}</td>
                  <td className="border p-2">{item.division?.division}</td>
                  <td className="border p-2">{item.position}</td>
                  <td className="border p-2">
                    {/* SEMUA AKSI TETAP */}
                    <div className="flex gap-2">
                      <button className="text-blue-500">Update</button>
                      <button className="text-red-500">Delete</button>
                      <button className="text-emerald-500">
                        Status Akun
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* PAGINATION */}
      <div className="flex justify-between items-center mt-4 text-sm">
        <span>
          Page {currentPage} of {totalPages || 1}
        </span>
        <div className="flex gap-2">
          <button
            disabled={currentPage === 1}
            onClick={() => setCurrentPage((p) => p - 1)}
            className="px-3 py-1 border rounded disabled:opacity-50"
          >
            Prev
          </button>
          <button
            disabled={currentPage === totalPages || totalPages === 0}
            onClick={() => setCurrentPage((p) => p + 1)}
            className="px-3 py-1 border rounded disabled:opacity-50"
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
}
